'use strict';
/* 验证码识别核心库：纯函数、零依赖、与扩展/浏览器完全解耦。
 * 输入统一为 { width, height, data: Uint8ClampedArray(RGBA) }。
 * 所有识别全程本地，不发起任何网络请求。 */
