  /** 提取拼图块 alpha 边缘点（相对块左上角）。 */
  function pieceEdgePoints(piece) {
    const { width, height, data } = piece;
    const alpha = (x, y) => data[(y * width + x) * 4 + 3];
    const pts = [];
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        if (alpha(x, y) < 128) continue;
        if (x === 0 || y === 0 || x === width - 1 || y === height - 1 ||
            alpha(x - 1, y) < 128 || alpha(x + 1, y) < 128 ||
            alpha(x, y - 1) < 128 || alpha(x, y + 1) < 128) {
          pts.push([x, y]);
        }
      }
    }
    return pts;
  }

  /**
   * 缺口定位：将拼图块边缘模板在背景边缘图上滑动匹配。
   * @returns {{x:number,y:number,confidence:number}|{skip:true,reason:string}}
   */
  function locateGap(bg, piece, opts = {}) {
    const minConfidence = opts.minConfidence ?? 0.35;
    const W = bg.width, H = bg.height, pw = piece.width, ph = piece.height;
    const edges = sobelMag(toGray(bg), W, H);
    const pts = pieceEdgePoints(piece);
    if (pts.length === 0) return { ...SKIP, reason: 'empty-piece-mask' };

    // 每个候选 (x,y) 的匹配得分 = 模板边缘点处背景边缘强度均值
    let best = { score: -1, x: 0, y: 0 };
    const scores = []; // 供置信度统计
    for (let y = 0; y <= H - ph; y += 1) {
      for (let x = 0; x <= W - pw; x += 1) {
        let s = 0;
        for (let k = 0; k < pts.length; k++) {
          s += edges[(y + pts[k][1]) * W + (x + pts[k][0])];
        }
        s /= pts.length;
        scores.push(s);
        if (s > best.score) best = { score: s, x, y };
      }
    }
    // 置信度：最佳分相对全局分布的 z-score 归一化 + 与次优峰（非邻域）的差距
    const mean = scores.reduce((a, b) => a + b, 0) / scores.length;
    const sd = Math.sqrt(scores.reduce((a, b) => a + (b - mean) ** 2, 0) / scores.length) || 1;
    let second = -1;
    for (let y = 0; y <= H - ph; y++) {
      for (let x = 0; x <= W - pw; x++) {
        if (Math.abs(x - best.x) < pw && Math.abs(y - best.y) < ph) continue;
        const s = scores[y * (W - pw + 1) + x];
        if (s > second) second = s;
