    const overshoot = distance > 30 ? 2 + rand() * 6 : 0;     // 过冲 2–8px
    const steps = Math.max(12, Math.round(duration / (10 + rand() * 8)));
    const points = [];
    let yOff = 0;
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      // 基础曲线：三次缓动（先加速后减速）
      const ease = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
      let x = ease * (distance + overshoot);
      // 末段 15%：回拉消除过冲
      if (t > 0.85) {
        const k = (t - 0.85) / 0.15;
