      const jitter = (rand() * 2 - 1) * 1.2 * (1 - t * 0.7);
      yOff += (rand() * 2 - 1) * 0.9;
      yOff *= 0.9; // 纵向随机游走带回归
      const ts = Math.round(t * duration + (rand() * 6 - 3));
      points.push({ x: Math.max(0, x + jitter), y: yOff, t: Math.max(0, ts) });
    }
    points[points.length - 1] = { x: distance, y: 0, t: duration }; // 精确落点
    return { points, duration };
