  const GLYPH = 16; // 归一化尺寸

  function otsuThreshold(gray) {
    const hist = new Array(256).fill(0);
    for (let i = 0; i < gray.length; i++) hist[gray[i] | 0]++;
    let sum = 0;
    for (let i = 0; i < 256; i++) sum += i * hist[i];
    let sumB = 0, wB = 0, best = 0, threshold = 127;
    for (let i = 0; i < 256; i++) {
      wB += hist[i];
      if (wB === 0) continue;
      const wF = gray.length - wB;
      if (wF === 0) break;
      sumB += i * hist[i];
      const mB = sumB / wB, mF = (sum - sumB) / wF;
      const between = wB * wF * (mB - mF) ** 2;
      if (between > best) { best = between; threshold = i; }
    }
    return threshold;
  }

  /** 二值化（暗色字符 → 1），返回 Uint8Array。 */
  function binarize(img) {
    const gray = toGray(img);
    const th = Math.min(otsuThreshold(gray), 160);
    const bin = new Uint8Array(img.width * img.height);
    for (let i = 0; i < gray.length; i++) bin[i] = gray[i] < th ? 1 : 0;
    return bin;
  }

  function inkBBox(bin, width, height) {
    let x0 = width, y0 = height, x1 = -1, y1 = -1;
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        if (!bin[y * width + x]) continue;
        if (x < x0) x0 = x;
        if (x > x1) x1 = x;
        if (y < y0) y0 = y;
        if (y > y1) y1 = y;
      }
    }
    return x1 < 0 ? null : { x0, y0, x1, y1 };
  }

  /** 裁剪 + 归一化到 GLYPH×GLYPH 的 0/1 向量。 */
  function normalizeGlyph(bin, width, box) {
    const w = box.x1 - box.x0 + 1, h = box.y1 - box.y0 + 1;
    const out = new Float32Array(GLYPH * GLYPH);
    for (let gy = 0; gy < GLYPH; gy++) {
      for (let gx = 0; gx < GLYPH; gx++) {
        const sx = box.x0 + Math.floor((gx / GLYPH) * w);
        const sy = box.y0 + Math.floor((gy / GLYPH) * h);
        out[gy * GLYPH + gx] = bin[sy * width + sx];
      }
    }
    return out;
  }

  /** 列投影切分：在墨迹包围盒内找 n-1 个最深谷值。 */
  function segmentGlyphs(bin, width, height, n) {
    const bbox = inkBBox(bin, width, height);
    if (!bbox) return [];
    const col = new Float32Array(width);
    for (let x = bbox.x0; x <= bbox.x1; x++) {
      for (let y = bbox.y0; y <= bbox.y1; y++) col[x] += bin[y * width + x];
    }
    // 平滑
    const sm = new Float32Array(width);
    for (let x = bbox.x0; x <= bbox.x1; x++) {
      sm[x] = (col[Math.max(bbox.x0, x - 1)] + col[x] + col[Math.min(bbox.x1, x + 1)]) / 3;
    }
    const cuts = [];
    const minGap = Math.max(4, ((bbox.x1 - bbox.x0 + 1) / n) * 0.5);
    while (cuts.length < n - 1) {
      let bestX = -1, bestV = Infinity;
      for (let x = bbox.x0 + 2; x <= bbox.x1 - 2; x++) {
        if (cuts.some(c => Math.abs(c - x) < minGap)) continue;
        if (sm[x] < bestV) { bestV = sm[x]; bestX = x; }
      }
      if (bestX < 0) break;
      cuts.push(bestX);
    }
    cuts.sort((a, b) => a - b);
    const bounds = [bbox.x0, ...cuts, bbox.x1 + 1];
    const glyphs = [];
    for (let i = 0; i < bounds.length - 1; i++) {
      const box = inkBBox(
        subBin(bin, width, bounds[i], bbox.y0, bounds[i + 1] - bounds[i], bbox.y1 - bbox.y0 + 1),
        bounds[i + 1] - bounds[i], bbox.y1 - bbox.y0 + 1);
      if (!box) { glyphs.push(null); continue; }
      glyphs.push({
        x0: bounds[i] + box.x0, y0: bbox.y0 + box.y0,
        x1: bounds[i] + box.x1, y1: bbox.y0 + box.y1,
      });
    }
    return glyphs;
  }

  function subBin(bin, width, x0, y0, w, h) {
    const out = new Uint8Array(w * h);
    for (let y = 0; y < h; y++) {
      out.set(bin.subarray((y0 + y) * width + x0, (y0 + y) * width + x0 + w), y * w);
    }
    return out;
  }

  /**
   * 训练本地原型模型：samples = [{ img, char }] → model（可 JSON 序列化）。
   * 每类取归一化位图均值作为原型（本地小模型，无外部 OCR）。
   */
  function trainModel(samples) {
    const sums = {}, counts = {};
    for (const { img, char } of samples) {
      const bin = binarize(img);
      const box = inkBBox(bin, img.width, img.height);
      if (!box) continue;
      const v = normalizeGlyph(bin, img.width, box);
      if (!sums[char]) { sums[char] = new Float32Array(GLYPH * GLYPH); counts[char] = 0; }
      for (let i = 0; i < v.length; i++) sums[char][i] += v[i];
      counts[char]++;
    }
    const classes = {};
    for (const c of Object.keys(sums)) {
      classes[c] = Array.from(sums[c], v => v / counts[c]);
    }
    return { glyphSize: GLYPH, classes };
  }

  function dist(a, b) {
    let s = 0;
    for (let i = 0; i < a.length; i++) { const d = a[i] - b[i]; s += d * d; }
    return Math.sqrt(s / a.length);
  }

  /**
   * 本地字符识别。
   * @returns {{text:string,confidence:number}|{skip:true,reason:string,confidence:number}}
   */
  function recognizeChars(img, model, opts = {}) {
    const n = opts.length ?? 4;
    const minConfidence = opts.minConfidence ?? 0.25;
    if (!model || !model.classes) return { ...SKIP, reason: 'no-model', confidence: 0 };
    const bin = binarize(img);
    const boxes = segmentGlyphs(bin, img.width, img.height, n);
    if (boxes.length !== n || boxes.some(b => !b)) {
      return { ...SKIP, reason: 'segmentation-failed', confidence: 0 };
    }
    const labels = Object.keys(model.classes);
    let text = '', confSum = 0;
    for (const box of boxes) {
      const v = normalizeGlyph(bin, img.width, box);
      let d1 = Infinity, d2 = Infinity, c1 = '';
      for (const c of labels) {
        const d = dist(v, model.classes[c]);
        if (d < d1) { d2 = d1; d1 = d; c1 = c; }
        else if (d < d2) d2 = d;
      }
      const conf = d2 > 0 ? Math.max(0, (d2 - d1) / d2) : 0;
      text += c1;
      confSum += conf;
    }
    const confidence = confSum / n;
    if (confidence < minConfidence) return { ...SKIP, confidence };
    return { text, confidence };
  }

  return {
    SKIP, toGray, sobelMag, locateGap, pieceEdgePoints,
    generateTrajectory, binarize, segmentGlyphs, normalizeGlyph,
    trainModel, recognizeChars, otsuThreshold,
  };
});
