const fs=require('fs');
const {decodePng}=require('./core/png');
const C=require('./core/solver');
const man=JSON.parse(fs.readFileSync('fixtures/manifest.json','utf8'));
function evalStrategy(scoreFn){
  let ok=0;const errs=[];
  for(const s of man.slider){
    const bg=decodePng(fs.readFileSync('fixtures/'+s.bg));
    const piece=decodePng(fs.readFileSync('fixtures/'+s.piece));
    const r=scoreFn(bg,piece);
    const e=Math.abs(r.x-s.gap_x);
    errs.push([s.name,e]);if(e<=3)ok++;
  }
  return ok+'/60 worst:'+errs.sort((a,b)=>b[1]-a[1]).slice(0,5).map(x=>x.join(':')).join(' ');
}
// 策略B: 边缘匹配 + 掩码内暗度
function stratB(bg,piece){
  const W=bg.width,H=bg.height,pw=piece.width,ph=piece.height;
  const gray=C.toGray(bg);
  const edges=C.sobelMag(gray,W,H);
  const pts=C.pieceEdgePoints(piece);
  // 掩码内部点
  const inPts=[];
  for(let y=0;y<ph;y++)for(let x=0;x<pw;x++)
    if(piece.data[(y*pw+x)*4+3]>=128 && (x+y)%3===0)inPts.push([x,y]);
  let best={score:-1,x:0,y:0};
  for(let y=0;y<=H-ph;y++)for(let x=0;x<=W-pw;x++){
    let se=0,sd=0;
    for(const[px,py]of pts)se+=edges[(y+py)*W+x+px];
    se/=pts.length;
    for(const[px,py]of inPts)sd+=gray[(y+py)*W+x+px];
    sd/=inPts.length;
    const score=se + 1.2*(255-sd);
    if(score>best.score)best={score,x,y};
  }
  return best;
}
console.log('B:',evalStrategy(stratB));
""}

