  const tm=tv.reduce((a,b)=>a+b,0)/n;
  const tc=tv.map(v=>v-tm);
  const tden=Math.sqrt(tc.reduce((a,b)=>a+b*b,0))||1;
  let best={score:-2,x:0,y:0};
