const fs=require('fs');
const {decodePng}=require('./core/png');
const C=require('./core/solver');
const man=JSON.parse(fs.readFileSync('fixtures/manifest.json','utf8'));
function solve(bg,piece,w){
  const W=bg.width,H=bg.height,pw=48,ph=48;
  const gray=C.toGray(bg);
  const edges=C.sobelMag(gray,W,H);
  const epts=C.pieceEdgePoints(piece);
  const inPts=[],outPts=[];
  for(let y=0;y<ph;y++)for(let x=0;x<pw;x++){
    const a=piece.data[(y*pw+x)*4+3]>=128;
    if(a&&(x*7+y*13)%5===0)inPts.push([x,y]);
  }
  // 外圈带：掩码外扩 2-5px 采样
  for(let y=-4;y<ph+4;y+=2)for(let x=-4;x<pw+4;x+=2){
    if(x<0||y<0||x>=pw||y>=ph)continue;
    const a=piece.data[(y*pw+x)*4+3]>=128;
    const near=piece.data[(y*pw+Math.min(pw-1,Math.max(0,x)))*4+3];
    if(!a)outPts.push([x,y]);
  }
  let best={score:-1e9,x:0,y:0};
  for(let y=4;y<=H-ph-4;y++)for(let x=4;x<=W-pw-4;x++){
    let se=0,si=0,so=0;
    for(const[px,py]of epts)se+=edges[(y+py)*W+x+px];
    se/=epts.length;
    for(const[px,py]of inPts)si+=gray[(y+py)*W+x+px];
    si/=inPts.length;
    for(const[px,py]of outPts)so+=gray[(y+py)*W+x+px];
    so/=outPts.length;
    const score=se + w*(so-si);
    if(score>best.score)best={score,x,y};
  }
  return best;
}
for(const w of [0.5,1,2]){
  let ok=0;const errs=[];
  for(const s of man.slider){
    const bg=decodePng(fs.readFileSync('fixtures/'+s.bg));
