'use strict';
const fs = require('node:fs');
const path = require('node:path');
const { decodePng } = require('../core/png');

const ROOT = path.join(__dirname, '..');
const FIXTURES = path.join(ROOT, 'fixtures');

function loadManifest() {
  return JSON.parse(fs.readFileSync(path.join(FIXTURES, 'manifest.json'), 'utf8'));
}
function loadImage(rel) {
  return decodePng(fs.readFileSync(path.join(FIXTURES, rel)));
}
function loadModel() {
  return JSON.parse(fs.readFileSync(path.join(ROOT, 'core', 'model.json'), 'utf8'));
}
/** 确定性随机源（可复现轨迹测试） */
function seededRandom(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 2 ** 32;
  };
}
module.exports = { ROOT, FIXTURES, loadManifest, loadImage, loadModel, seededRandom };
