'use strict';
/* 缺口定位精度：噪点/渐变/伪缺口干扰下误差 ≤ 3px、成功率 ≥ 90% */
const test = require('node:test');
const assert = require('node:assert/strict');
const { locateGap } = require('../core/solver');
const { loadManifest, loadImage } = require('./helpers');

const TOLERANCE_PX = 3;
const MIN_SUCCESS = 0.9;

test('slider gap localization accuracy', () => {
  const { slider } = loadManifest();
  assert.ok(slider.length >= 50, 'fixture 数量不足');
  let ok = 0, skipped = 0;
  const errors = [];
  for (const s of slider) {
    const r = locateGap(loadImage(s.bg), loadImage(s.piece));
    if (r.skip) { skipped++; continue; }
    const err = Math.abs(r.x - s.gap_x);
    errors.push(err);
    if (err <= TOLERANCE_PX) ok++;
  }
  const rate = ok / slider.length;
  console.log(`  gap: ${ok}/${slider.length} within ${TOLERANCE_PX}px` +
    ` (${(rate * 100).toFixed(1)}%), skipped=${skipped}`);
  assert.ok(rate >= MIN_SUCCESS, `成功率 ${(rate * 100).toFixed(1)}% < ${MIN_SUCCESS * 100}%`);
});

test('locateGap returns confidence and skips on garbage input', () => {
  const blank = { width: 100, height: 60, data: new Uint8ClampedArray(100 * 60 * 4).fill(255) };
  const piece = { width: 20, height: 20, data: new Uint8ClampedArray(20 * 20 * 4).fill(0) };
  const r = locateGap(blank, piece);
  assert.ok(r.skip === true || typeof r.confidence === 'number');
});
