'use strict';
/* 拟人轨迹统计特征：时长、速度曲线、随机抖动、回拉 */
const test = require('node:test');
const assert = require('node:assert/strict');
const { generateTrajectory } = require('../core/solver');
const { seededRandom } = require('./helpers');

const DIST = 180;

test('trajectory duration and endpoint', () => {
  for (let seed = 1; seed <= 20; seed++) {
    const { points, duration } = generateTrajectory(DIST, { random: seededRandom(seed) });
    assert.ok(duration >= 500 && duration <= 1300, `时长 ${duration}ms 超出人类范围`);
    assert.ok(points.length >= 12, '采样点过少');
    const last = points[points.length - 1];
    assert.equal(last.x, DIST, '落点必须精确等于目标距离');
    assert.equal(last.t, duration);
    assert.ok(points[0].t >= 0);
  }
});

test('trajectory has overshoot + pullback (回拉)', () => {
  let withOvershoot = 0;
  for (let seed = 1; seed <= 20; seed++) {
    const { points } = generateTrajectory(DIST, { random: seededRandom(seed) });
    const maxX = Math.max(...points.map(p => p.x));
    if (maxX > DIST + 0.5) {
      withOvershoot++;
      const peakIdx = points.findIndex(p => p.x === maxX);
      assert.ok(peakIdx < points.length - 1, '过冲后必须有回拉段');
    }
  }
  assert.ok(withOvershoot >= 15, `过冲样本过少: ${withOvershoot}/20`);
});

test('trajectory velocity profile: 加速-减速，峰值在中段', () => {
  const { points } = generateTrajectory(DIST, { random: seededRandom(7) });
  const xs = points.map(p => p.x);
  const ts = points.map(p => p.t);
  const v = [];
  for (let i = 1; i < points.length; i++) {
    const dt = ts[i] - ts[i - 1];
    v.push(dt > 0 ? (xs[i] - xs[i - 1]) / dt : 0);
  }
  const peakIdx = v.indexOf(Math.max(...v));
  const frac = peakIdx / v.length;
  assert.ok(frac > 0.15 && frac < 0.85, `速度峰值位置 ${frac.toFixed(2)} 不在中段`);
  assert.ok(Math.abs(v[0]) < Math.max(...v) * 0.6, '起步速度应较低');
});

test('trajectory has random jitter (非机械直线)', () => {
  const { points } = generateTrajectory(DIST, { random: seededRandom(11) });
  const ys = points.map(p => p.y);
  const mean = ys.reduce((a, b) => a + b, 0) / ys.length;
  const variance = ys.reduce((a, b) => a + (b - mean) ** 2, 0) / ys.length;
  assert.ok(variance > 0.01, '纵向抖动方差过小，轨迹过于机械');
  const steps = [];
  for (let i = 1; i < points.length; i++) steps.push(points[i].x - points[i - 1].x);
  const uniq = new Set(steps.map(s => s.toFixed(3)));
  assert.ok(uniq.size > steps.length * 0.8, '步长过于均匀');
});

test('trajectory reproducible with seeded random', () => {
  const a = generateTrajectory(DIST, { random: seededRandom(42) });
  const b = generateTrajectory(DIST, { random: seededRandom(42) });
  assert.deepEqual(a, b);
});
