'use strict';
/* 内容脚本：检测演示页中的验证码组件并本地求解。
 * 识别全程本地（CaptchaCore + CaptchaModel 均随扩展打包），不发起任何网络请求。
 * 低置信度时标记「跳过/人工」，不硬猜。 */
(function () {
  const Core = self.CaptchaCore;
  const MODEL = self.CaptchaModel;

  function mark(el, status, msg) {
    el.dataset.solverStatus = status;
    el.dispatchEvent(new CustomEvent('captcha-solver', {
      bubbles: true, detail: { status, message: msg },
    }));
  }

  function imageToImageData(img) {
    const c = document.createElement('canvas');
    c.width = img.naturalWidth;
    c.height = img.naturalHeight;
    const ctx = c.getContext('2d', { willReadFrequently: true });
    ctx.drawImage(img, 0, 0);
    return ctx.getImageData(0, 0, c.width, c.height);
  }

  function dispatchDrag(handle, dx, points, done) {
    const rect = handle.getBoundingClientRect();
    const sx = rect.left + rect.width / 2;
    const sy = rect.top + rect.height / 2;
    const opts = (x, y) => ({ bubbles: true, clientX: x, clientY: y, pointerId: 1 });
    handle.dispatchEvent(new PointerEvent('pointerdown', opts(sx, sy)));
    let i = 0;
    const t0 = performance.now();
    function step() {
      if (i >= points.length) {
        handle.dispatchEvent(new PointerEvent('pointerup', opts(sx + dx, sy)));
        done();
        return;
      }
      const p = points[i++];
      const wait = p.t - (performance.now() - t0);
      setTimeout(() => {
        handle.dispatchEvent(new PointerEvent('pointermove', opts(sx + p.x, sy + p.y)));
        step();
      }, Math.max(0, wait));
    }
    step();
  }

  function solveSlider(root) {
    const bgImg = root.querySelector('img[data-role="bg"]');
    const pieceImg = root.querySelector('img[data-role="piece"]');
    const handle = root.querySelector('[data-role="handle"]');
    if (!bgImg || !pieceImg || !handle) return;
    let r;
    try {
      r = Core.locateGap(imageToImageData(bgImg), imageToImageData(pieceImg));
    } catch (e) {
      mark(root, 'skip', '定位异常: ' + e.message);
      return;
    }
    if (r.skip) {
      mark(root, 'skip', `置信度过低(${(r.confidence || 0).toFixed(2)})，跳过/人工`);
      return;
    }
    const scale = bgImg.getBoundingClientRect().width / bgImg.naturalWidth;
    const distance = Math.round(r.x * scale) - (parseInt(root.dataset.pieceOffset || '0', 10));
    const traj = Core.generateTrajectory(distance);
    mark(root, 'solving', `缺口 x=${r.x} 置信度=${r.confidence.toFixed(2)}，拟人拖动 ${distance}px`);
    dispatchDrag(handle, distance, traj.points, () => mark(root, 'done', '拖动完成'));
  }

  function solveChars(root) {
    const img = root.querySelector('img[data-role="captcha-img"]');
    const input = root.querySelector('input[data-role="answer"]');
    const btn = root.querySelector('[data-role="verify"]');
    if (!img || !input || !btn) return;
    let r;
    try {
      r = Core.recognizeChars(imageToImageData(img), MODEL);
    } catch (e) {
      mark(root, 'skip', '识别异常: ' + e.message);
      return;
    }
    if (r.skip) {
      mark(root, 'skip', `置信度过低(${(r.confidence || 0).toFixed(2)})，跳过/人工`);
      return;
    }
    input.value = r.text;
    mark(root, 'solving', `识别=${r.text} 置信度=${r.confidence.toFixed(2)}`);
    btn.click();
    mark(root, 'done', '已提交');
  }

  function scan() {
    document.querySelectorAll('[data-captcha="slider"]:not([data-solver-status])')
      .forEach(solveSlider);
    document.querySelectorAll('[data-captcha="chars"]:not([data-solver-status])')
      .forEach(solveChars);
  }

  if (document.readyState === 'complete') scan();
  else window.addEventListener('load', scan);
  new MutationObserver(() => scan()).observe(document.documentElement,
    { childList: true, subtree: true });
})();
