function setupSlider() {
  const card = document.getElementById('sliderCard');
  const bg = card.querySelector('[data-role="bg"]');
  const piece = card.querySelector('[data-role="piece"]');
  const handle = card.querySelector('[data-role="handle"]');
  const status = card.querySelector('[data-role="status"]');
  let truth = null, pieceX = 0, dragging = false, startX = 0;

  function load() {
    truth = MANIFEST.slider[Math.floor(Math.random() * MANIFEST.slider.length)];
    bg.src = '../fixtures/' + truth.bg;
    piece.src = '../fixtures/' + truth.piece;
    pieceX = 0;
    piece.style.left = '0px';
    piece.style.top = truth.gap_y + 'px';
    handle.style.top = truth.gap_y + 'px';
    handle.style.left = '0px';
    delete card.dataset.solverStatus;
    status.className = 'status info';
    status.textContent = '等待求解…（可手动拖动，或由扩展/内置核心自动通过）';
  }

  function verify() {
    const err = Math.abs(pieceX - truth.gap_x);
    const pass = err <= 4;
    status.className = 'status ' + (pass ? 'pass' : 'fail');
    status.textContent = (pass ? '✓ 通过' : '✗ 未通过') +
      `（落点 ${Math.round(pieceX)}px，目标 ${truth.gap_x}px，误差 ${Math.round(err)}px）`;
    log(`滑块验证: ${pass ? '通过' : '失败'} 误差=${Math.round(err)}px`);
  }

  handle.addEventListener('pointerdown', e => {
    dragging = true; startX = e.clientX - pieceX;
    handle.setPointerCapture(e.pointerId);
  });
  handle.addEventListener('pointermove', e => {
    if (!dragging) return;
    pieceX = Math.max(0, Math.min(300 - 48, e.clientX - startX));
    piece.style.left = pieceX + 'px';
    handle.style.left = pieceX + 'px';
  });
  handle.addEventListener('pointerup', () => { if (dragging) { dragging = false; verify(); } });

  card.querySelector('[data-role="reload"]').onclick = load;
  card.querySelector('[data-role="builtin-solve"]').onclick = async () => {
    const toData = img => {
      const c = document.createElement('canvas');
      c.width = img.naturalWidth; c.height = img.naturalHeight;
      const x = c.getContext('2d', { willReadFrequently: true });
      x.drawImage(img, 0, 0);
      return x.getImageData(0, 0, c.width, c.height);
    };
    const r = Core.locateGap(toData(bg), toData(piece));
    if (r.skip) {
      status.className = 'status fail';
      status.textContent = `置信度过低(${(r.confidence || 0).toFixed(2)})，跳过/人工`;
      log('内置核心: 滑块低置信度，跳过');
      return;
    }
    const traj = Core.generateTrajectory(r.x);
    log(`内置核心: 缺口 x=${r.x} 置信度=${r.confidence.toFixed(2)} 轨迹点=${traj.points.length}`);
    const rect = handle.getBoundingClientRect();
    const sx = rect.left + 24, sy = rect.top + 24;
    const opt = (x, y) => ({ bubbles: true, clientX: x, clientY: y, pointerId: 1 });
    handle.dispatchEvent(new PointerEvent('pointerdown', opt(sx, sy)));
    const t0 = performance.now();
    for (const p of traj.points) {
      const wait = p.t - (performance.now() - t0);
      if (wait > 0) await new Promise(res => setTimeout(res, wait));
      handle.dispatchEvent(new PointerEvent('pointermove', opt(sx + p.x, sy + p.y)));
    }
    handle.dispatchEvent(new PointerEvent('pointerup', opt(sx + r.x, sy)));
  };
  load();
}

/* ================= 字符组件 ================= */
function setupChars() {
  const card = document.getElementById('charsCard');
  const img = card.querySelector('[data-role="captcha-img"]');
  const input = card.querySelector('[data-role="answer"]');
  const status = card.querySelector('[data-role="status"]');
  let truth = null;

  function load() {
    truth = MANIFEST.chars[Math.floor(Math.random() * MANIFEST.chars.length)];
    img.src = '../fixtures/' + truth.image;
    input.value = '';
    delete card.dataset.solverStatus;
    status.className = 'status info';
    status.textContent = '等待识别…（可手动输入，或由扩展/内置核心自动识别）';
  }
  function verify() {
    const pass = input.value.trim().toUpperCase() === truth.text;
    status.className = 'status ' + (pass ? 'pass' : 'fail');
    status.textContent = pass ? '✓ 通过' : `✗ 未通过（答案 ${truth.text}）`;
    log(`字符验证: ${pass ? '通过' : '失败'} 输入=${input.value}`);
  }
  card.querySelector('[data-role="verify"]').onclick = verify;
  card.querySelector('[data-role="reload"]').onclick = load;
  card.querySelector('[data-role="builtin-solve"]').onclick = () => {
    const c = document.createElement('canvas');
    c.width = img.naturalWidth; c.height = img.naturalHeight;
    const x = c.getContext('2d', { willReadFrequently: true });
    x.drawImage(img, 0, 0);
    const r = Core.recognizeChars(x.getImageData(0, 0, c.width, c.height), MODEL);
    if (r.skip) {
      status.className = 'status fail';
      status.textContent = `置信度过低(${(r.confidence || 0).toFixed(2)})，跳过/人工`;
      log('内置核心: 字符低置信度，跳过');
      return;
    }
    input.value = r.text;
    log(`内置核心: 识别=${r.text} 置信度=${r.confidence.toFixed(2)}`);
    verify();
  };
  load();
}

boot();
</script>
</body>
</html>
